import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  componentStack: string | null;
  errorId: string | null;
}

function generateErrorId(): string {
  return `err_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, componentStack: null, errorId: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error, errorId: generateErrorId() };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    const { errorId } = this.state;
    console.error("[ErrorBoundary]", {
      errorId,
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
    });
    this.setState({ componentStack: info.componentStack ?? null });
    this.props.onError?.(error, info);
  }

  reset = (): void => {
    this.setState({ error: null, componentStack: null, errorId: null });
  };

  render(): ReactNode {
    const { error, componentStack, errorId } = this.state;

    if (error) {
      if (this.props.fallback) return this.props.fallback;

      return (
        <div role="alert" style={{ padding: "1rem", border: "1px solid red", fontFamily: "monospace" }}>
          <h2 style={{ margin: "0 0 0.5rem" }}>Something went wrong</h2>
          <p style={{ color: "red", margin: "0 0 0.25rem" }}>{error.message}</p>
          {errorId && (
            <p style={{ fontSize: "0.75rem", color: "#888", margin: "0 0 0.5rem" }}>
              Error ID: {errorId}
            </p>
          )}
          {componentStack && (
            <details style={{ marginBottom: "0.75rem" }}>
              <summary style={{ cursor: "pointer", fontSize: "0.85rem" }}>Component stack</summary>
              <pre style={{ whiteSpace: "pre-wrap", fontSize: "0.75rem", color: "#555", marginTop: "0.25rem" }}>
                {componentStack}
              </pre>
            </details>
          )}
          <button onClick={this.reset}>Try Again</button>
        </div>
      );
    }

    return this.props.children;
  }
}
